"""Offer Builder: valid term sheets of equal value to the supplier, cheapest for us first.

For every combination of the non-price levers the price is solved so that the package is worth a
target amount to the supplier (`cost.supplier_value`: a cash-short supplier values early payment).
The target walks from our aspiration towards the supplier's standing offer along a concession
schedule; `trade` packages are worth exactly as much to it as its own offer but cost us less.
"""

import itertools
import math

from arena_kit.cost import RELATIONSHIP_GOALS, must_haves_ok, supplier_value
from arena_kit.harness.valuation import effort, value

from . import priors

MAX_COMBOS = 300
PER_LEVEL = 8
# Own-plant should-cost estimates ran about 2 % above the full cost the arena's relationship term implied
# (practice P01, P02, P03 results: 130.0 vs 132.6, 367.4 vs 375.0, 394.7 vs 403.2).
SHOULD_COST_BIAS = 0.02
ANCHOR_FLOOR = 0.65  # never ask below this share of the standing price


def lever_domains(case, std):
    """{field: [allowed values]} for the non-price negotiable fields, or None if one has none."""
    out = {}
    for field in case["negotiable"]:
        if field == "unit_price":
            continue
        values = list(case.get("term_options", {}).get(field) or [])
        if field in std and std[field] not in values:
            values.append(std[field])
        if not values:
            return None
        out[field] = values
    return out


def _prune(domains, base):
    """Keep the product small: shrink the longest field to a spread (its ends, middle and the supplier's
    own value) until the product fits."""
    cap = 4
    orig = {f: list(v) for f, v in domains.items()}
    while math.prod(len(v) for v in domains.values()) > MAX_COMBOS and cap >= 1:
        field = max(domains, key=lambda f: len(domains[f]))
        if len(domains[field]) <= cap:
            cap -= 1
            continue
        values = orig[field]  # always spread over the full option list, not an already pruned one
        keep = [base.get(field)] if base.get(field) in values else []
        spread = [values[0], values[-1], values[len(values) // 2], *values[1:-1]]
        for v in spread:
            if len(keep) >= cap:
                break
            if v not in keep:
                keep.append(v)
        domains[field] = keep
    return domains


def supplier_standard(case, led):
    """Its standard terms for valuation: stated at the opening, then the standard section, plan gaps."""
    b = case["buyer"]
    std = {**{k: v for k, v in (led.get("stated_open") or {}).items() if k != "unit_price"}, **(led.get("std") or {})}
    std.setdefault("payment_days", b["reference_payment_days"])
    if "incoterm" not in std:
        std["incoterm"] = case.get("fixed_terms", {}).get("incoterm") or "EXW"
    return std


def should_cost_row(parts_dossier, sid):
    """The should-cost estimate of this supplier's own plant, else a generic one (no supplier), else None.
    Another supplier's plant estimate says nothing about this one's costs."""
    rows = [
        sc
        for part in (parts_dossier or {}).values()
        for sc in part.get("should_cost", [])
        if sc.get("unit_cost") and sc.get("price_unit") in (None, 1)
    ]
    for pick in ([r for r in rows if r.get("supplier_id") == sid], [r for r in rows if not r.get("supplier_id")]):
        if pick:
            return min(pick, key=lambda r: r["unit_cost"])
    return None


def supplier_model(case, led, tags, dossier_sup, parts_dossier):
    """Our estimate of the supplier for `supplier_value` / the relationship term."""
    model = {
        "standard": supplier_standard(case, led),
        "interest_rate": priors.rate_for(tags),
        "usual_rate": 0.07,
        "ref_price": led.get("price") or 0.0,
    }
    b = case["buyer"]
    if b.get("category_goal") in RELATIONSHIP_GOALS:
        row = should_cost_row(parts_dossier, led.get("supplier_id"))
        # Generic plant estimates are a prior, not a supplier's revealed cost floor.
        own_plant = bool(row and row.get("supplier_id") == led.get("supplier_id"))
        full = row["unit_cost"] * (1 - SHOULD_COST_BIAS) if own_plant else None
        opening = next((p for p in led.get("prices", []) if p), led.get("price"))
        sustainable = b.get("sustainable_margin_pct") or 8
        if full is None and opening:
            full = opening * (1 - (sustainable + 2) / 100)
        if led.get("breakdown_total"):
            full = led["breakdown_total"]
        if full and opening:
            # A supplier quotes at least its sustainable margin at its own standard terms: an estimate
            # above that is a bad estimate (practice P02: should-cost above the quote emptied the menu).
            full = min(full, opening * (1 - sustainable / 100))
        if full:
            model["full_cost"] = full
            model["cost_uncertainty_pct"] = (row or {}).get("confidence_pct", 15)
            model["cost_source"] = row.get("id") if own_plant else "opening-price prior"
    return model


def _value(case, terms, model):
    try:
        return supplier_value(case, terms, {**model, "extra": model.get("extra", 0.0) - effort(terms, model)})
    except Exception:
        return None


def solve_price(case, levers, model, target):
    """Unit price (2 decimals) that makes the package worth `target` to the supplier."""
    v0 = _value(case, {**levers, "unit_price": 0.0}, model)
    v1 = _value(case, {**levers, "unit_price": 1.0}, model)
    if v0 is None or v1 is None or v1 - v0 <= 1e-9:
        return None
    price = (target - v0) / (v1 - v0)
    return round(price, 2) if price > 0 else None


def cost(case, terms, std, model):
    try:
        sup = None
        if case["buyer"].get("category_goal") in RELATIONSHIP_GOALS and model.get("full_cost"):
            sup = model
        c = value(case, terms, std, sup)["cost"]
        return c if math.isfinite(c) else None
    except Exception:
        return None


def anchor_price(case, led, tags, dossier, drop, rivals=None, model=None, std=None):
    """First ask: ambitious but defensible.

    - the standing price minus `drop` (scaled by what the supplier's situation allows);
    - in an increase/renewal: at or below what we pay today - the increase still has to be earned;
    - in an RFQ: below the cheapest rival bid (`rivals`: other bidders' standing prices);
    - never below this supplier's own should-cost band, nor below the price where squeezing it starts to
      cost us more than it saves (relationship goals, via our cost model), nor below ANCHOR_FLOOR.
    """
    standing = led["price"]
    b = case["buyer"]
    factor = 1.0
    for t in tags:
        factor *= {
            "full_order_book": 0.5,
            "not_strategic": 0.7,
            "price_frozen": 0.5,
            "spare_capacity": 1.3,
            "weak_costing": 1.2,
            "cash_short": 0.8,
            "hedged_forward": 1.2,
            "open_books": 1.1,
        }.get(t, 1.0)
    cut = min(0.35, drop * factor)
    target = standing * (1 - cut)
    current = b.get("current_unit_price")
    if current and case.get("type") in ("price_increase", "renewal", "raw_material") and current < standing:
        target = min(target, current * (1 - cut / 3))
    cheapest_rival = min((p for p in (rivals or []) if p), default=None)
    if cheapest_rival:
        target = min(target, cheapest_rival * (1 - cut))
    row = should_cost_row(dossier.get("parts"), led.get("supplier_id"))
    if row and row.get("supplier_id") == led.get("supplier_id"):
        lower = row["unit_cost"] * (1 - (row.get("confidence_pct") or 15) / 100)
        # Even an own-plant estimate cannot contradict the supplier's observed offer.
        target = max(target, min(lower, standing * (1 - drop)))
    if model and model.get("full_cost") and std is not None:
        target = max(target, cheapest_price(case, led, model, std, target, standing))
    return round(max(min(target, standing), standing * ANCHOR_FLOOR), 2)


def cheapest_price(case, led, model, std, low, high):
    """The price at the supplier's standing levers below which our modelled cost rises again (squeezing
    a relationship supplier below its sustainable margin costs more than it saves)."""
    terms = dict(led.get("terms") or {})
    if not terms or high <= low:
        return low

    def c(p):
        return cost(case, {**terms, "unit_price": round(p, 2)}, std, model) or math.inf

    best_p, best_c = high, c(high)
    for i in range(41):
        p = low + (high - low) * i / 40
        v = c(p)
        if v < best_c - 1e-6:
            best_p, best_c = p, v
    return best_p


def price_for_cost(case, levers, std, model, c_target, lo, hi):
    """Unit price (2 decimals) at which `levers` cost us `c_target` (bisection: the relationship term is
    not linear), or None if no price in [lo, hi] gets there."""

    def c(p):
        return cost(case, {**levers, "unit_price": round(p, 2)}, std, model)

    c_lo, c_hi = c(lo), c(hi)
    if c_lo is None or c_hi is None or c_lo > c_target:
        return None
    if c_hi <= c_target:
        return round(hi, 2)
    for _ in range(40):
        mid = (lo + hi) / 2
        cm = c(mid)
        if cm is None:
            return None
        lo, hi = (mid, hi) if cm <= c_target else (lo, mid)
    return math.floor(lo * 100) / 100


def schedule(k, horizon):
    """Share of the way from our aspiration to its offer after k of our messages (slow early)."""
    if horizon <= 1:
        return 1.0
    return min(1.0, (k / (horizon - 1)) ** 2)


def build_menu(case, led, model, std, v_asp, v_stand, levels, must_beat):
    """Candidates [{mid, level, terms, c, saving, price, changes}] for the given {level: share} map."""
    domains = lever_domains(case, std)
    if domains is None or v_asp is None or v_stand is None:
        return []
    base = model["standard"]
    domains = _prune(domains, base)
    names = list(domains)
    combos = [dict(zip(names, values, strict=True)) for values in itertools.product(*domains.values())] or [{}]
    menu, seen = [], set()
    for level, share in levels.items():
        target = v_asp + (v_stand - v_asp) * share
        found = []
        for levers in combos:
            price = solve_price(case, levers, model, target)
            if price is None:
                continue
            terms = {**levers, "unit_price": price}
            terms = {f: terms[f] for f in case["negotiable"]}
            if not must_haves_ok(case, terms, std):
                continue
            c = cost(case, terms, std, model)
            if c is None or c >= must_beat - 0.5:
                continue
            changes = sum(levers.get(k) != base.get(k) for k in levers)
            found.append((c, changes, terms))
        found.sort(key=lambda x: (x[0], x[1]))  # ties: stay close to the supplier's own terms
        # Keep each lever's alternatives represented before filling with cheap near-duplicates.
        # Supplier security (indexation/duration) is deliberately outside supplier_value's cash formula.
        diverse, represented = [], set()
        for candidate in found:
            terms = candidate[2]
            features = {(f, str(terms.get(f))) for f in names}
            if not diverse or features - represented:
                diverse.append(candidate)
                represented |= features
        ordered = diverse + [x for x in found if x not in diverse]
        picked = 0
        for c, _, terms in ordered:
            key = tuple(sorted((k, str(v)) for k, v in terms.items()))
            profile = tuple(sorted((k, str(v)) for k, v in terms.items() if k != "unit_price"))
            same_level = [m for m in menu if m["level"] == level]
            if key in seen or profile in {m["profile"] for m in same_level}:
                continue
            seen.add(key)
            menu.append(
                {
                    "level": level,
                    "terms": terms,
                    "c": round(c, 2),
                    "saving": round(must_beat - c, 2),
                    "price": terms.get("unit_price"),
                    "changes": {k: v for k, v in terms.items() if k != "unit_price" and base.get(k) != v},
                    "profile": profile,
                }
            )
            picked += 1
            if picked >= PER_LEVEL:
                break
    for i, m in enumerate(menu, 1):
        m["mid"] = f"M{i}"
        m.pop("profile", None)
    return menu


def describe(case, terms):
    """One human line per sheet, written by code (figures never come from the model)."""
    parts = [f"unit price EUR {terms['unit_price']:.2f}"] if terms.get("unit_price") is not None else []
    labels = {
        "payment_days": lambda v: f"payment {v} days net",
        "lead_time_days": lambda v: f"lead time {v} days",
        "volume_per_year": lambda v: f"{v} pieces a year",
        "contract_months": lambda v: "single order" if v == 0 else f"contract {v} months",
        "effective_date": lambda v: f"valid from {v}",
        "incoterm": lambda v: f"Incoterm {v}",
        "tooling_eur": lambda v: f"tooling EUR {v:,.0f}",
        "ppm_commitment": lambda v: f"quality commitment {v} ppm",
        "chargeback_eur_per_complaint": lambda v: f"chargeback EUR {v} per complaint",
        "index_clause": lambda v: (
            "no index clause"
            if not v
            else f"index clause on {v.get('series')} ({round(100 * v.get('material_share', 0))}% material)"
        ),
    }
    for field in case["negotiable"]:
        if field != "unit_price" and field in terms:
            fmt = labels.get(field, lambda v, f=field: f"{f.replace('_', ' ')} {v}")
            try:
                parts.append(fmt(terms[field]))
            except Exception:
                parts.append(f"{field} {terms[field]}")
    return ", ".join(parts)
"""Observer: one ledger per supplier thread - what it offers, how it moved, how our claims landed."""

import math

from arena_kit.docs import quote_terms, standard_terms
from arena_kit.harness.validation import acceptable
from arena_kit.harness.valuation import ranked_offers, value
from arena_kit.play import ENDED, latest, moves_left, standing

TEXT_CHARS = 1200
ATTACH_CHARS = 1500


def _quote_sections(events):
    """Sections of the first readable quote PDF in the thread (the opening offer)."""
    for msg in events:
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote") and att.get("text"):
                try:
                    return quote_terms(att["text"])
                except Exception:
                    return {}
    return {}


def build(case, threads, models=None):
    out = {}
    for sid, events in threads.items():
        led = {"supplier_id": sid}
        try:
            last = latest(events)
        except StopIteration:
            continue
        offer_id, terms = standing(events)
        model = (models or {}).get(sid)
        ranked = ranked_offers(case, events, model)
        # Only the standing (first) sheet can be accepted; a cheaper alternative is mirrored back instead.
        primary = [s for s in ranked if s.get("primary", True)]
        eligible = [s for s in primary if s["beats_alternative"]]
        best = None
        if eligible or primary:
            best = (eligible or primary)[0]
            offer_id, terms = best["term_sheet_id"], best["terms"]
        alts = [s for s in ranked if not s.get("primary", True) and s["beats_alternative"]]
        led["alt_better"] = (
            {"term_sheet_id": alts[0]["term_sheet_id"], "terms": alts[0]["terms"], "cost": alts[0]["cost"]}
            if alts and best is not None and alts[0]["cost"] < best["cost"] - 1.0
            else None
        )
        led["offers"] = ranked
        led["model"] = model
        led.update(offer_id=offer_id, terms=terms, price=terms.get("unit_price"), status=last.get("status"))
        led["ended"] = last.get("status") in ENDED
        led["std"] = standard_terms(events)
        led["stated_open"] = _quote_sections(events).get("stated", {})
        try:
            valuation = value(case, terms, led["std"], model) if terms else {}
            c = valuation.get("cost", math.inf)
            led.update(
                known_cost=valuation.get("known_cost"), relationship_estimate=valuation.get("relationship_estimate")
            )
        except Exception:
            c = math.inf
        led["c"] = c if math.isfinite(c) else None
        supplier_msgs = [m for m in events if m.get("from") != "buyer"]
        buyer_msgs = [m for m in events if m.get("from") == "buyer"]
        led["prices"] = [(m.get("term_sheets") or [{}])[0].get("terms", {}).get("unit_price") for m in supplier_msgs]
        led["statuses"] = [m.get("status") for m in supplier_msgs]
        led["rounds"] = len(buyer_msgs)
        led["moves_left"] = moves_left(case, events)
        led["our_sheets"] = [[s.get("terms", {}) for s in m.get("term_sheets") or []] for m in buyer_msgs]
        led["missing_fields"] = last.get("missing_fields") or []
        led["claim_results"] = [r.get("result") for r in last.get("claim_results") or []]
        led["claims_total"] = {}
        for m in supplier_msgs:
            for r in m.get("claim_results") or []:
                led["claims_total"][r.get("result")] = led["claims_total"].get(r.get("result"), 0) + 1
        led["from"] = last.get("from")
        led["body"] = (last.get("body") or "")[:TEXT_CHARS]
        led["message_id"] = last.get("message_id")
        led["signals"] = last.get("signals") or {}
        prices = [p for p in led["prices"] if p]
        led["move_pct"] = round((prices[-2] - prices[-1]) / prices[-2] * 100, 2) if len(prices) >= 2 else None
        led["total_move_pct"] = round((prices[0] - prices[-1]) / prices[0] * 100, 2) if len(prices) >= 2 else 0.0
        first_final = next((i for i, s in enumerate(led["statuses"]) if s == "final_offer"), None)
        # supplier message i answers buyer message i-1 (message 0 is the opening quote)
        # only messages with term sheets push; a holding note without sheets does not
        led["pushes_after_final"] = (
            0 if first_final is None else sum(bool(m.get("term_sheets")) for m in buyer_msgs[first_final:])
        )
        led["attachments"] = [
            {"name": a.get("name"), "text": (a.get("text") or "")[:ATTACH_CHARS]}
            for a in last.get("attachments") or []
            if a.get("text") and not a.get("name", "").startswith("quote")
        ]
        led["breakdown"] = any(
            "breakdown" in (a.get("name") or "").lower() for m in supplier_msgs for a in m.get("attachments") or []
        )
        try:
            led["acceptable"] = bool(eligible) and not led["ended"] and acceptable(case, events, offer_id)
        except Exception:
            led["acceptable"] = False
        out[sid] = led
    return out


def digest(led):
    """Compact view for the prompt."""
    return {
        "status": led.get("status"),
        "from": led.get("from"),
        "standing_terms": led.get("terms"),
        "standing_cost_eur": led.get("c"),
        "known_cost_eur": led.get("known_cost"),
        "relationship_estimate_eur": led.get("relationship_estimate"),
        "supplier_cost_assumption": led.get("model"),
        "current_offers": led.get("offers"),
        "price_path": led.get("prices"),
        "status_path": led.get("statuses"),
        "our_messages": led.get("rounds"),
        "moves_left": led.get("moves_left"),
        "last_move_pct": led.get("move_pct"),
        "claims_last": led.get("claim_results"),
        "claims_total": led.get("claims_total"),
        "missing_fields": led.get("missing_fields"),
        "standard_terms": led.get("std"),
        "signals": led.get("signals"),
        "latest_email": led.get("body"),
        "attachments": led.get("attachments"),
    }

MENU_BAND = 0.003  # sheets of one level may cost us at most this much more than the level's cheapest


def within_band(menu, case=None, std=None, model=None, pref=None, standing_price=None):
    """Of equal-value sheets the supplier takes the one dearest for us (practice P05: 14 days' payment,
    P08/P18: the index clause, P10/P11: lead time and ppm): offer only sheets that cost us about the same.
    A lever the supplier has insisted on (`pref`) is kept - repriced so that it, too, costs us the level's
    cheapest C: an index clause then comes with a lower base price."""
    floor = {}
    for m in menu:
        floor[m["level"]] = min(floor.get(m["level"], m["c"]), m["c"])
    out = [m for m in menu if m["c"] <= floor[m["level"]] * (1 + MENU_BAND)]
    fields = (pref or {}).get("fields") or {}
    if not fields or case is None:
        return out
    hi = standing_price or max((m["price"] or 0) for m in menu) if menu else 0
    for level, c_floor in floor.items():
        if any(all(m["terms"].get(f) in p["values"] for f, p in fields.items()) for m in out if m["level"] == level):
            continue
        wanted = [
            m for m in menu if m["level"] == level and all(m["terms"].get(f) in p["values"] for f, p in fields.items())
        ]
        if not wanted:
            continue
        best = min(wanted, key=lambda m: m["c"])
        levers = {k: v for k, v in best["terms"].items() if k != "unit_price"}
        price = offers.price_for_cost(case, levers, std, model, c_floor, 0.5 * (hi or best["price"]), best["price"])
        if price and price > 0:
            terms = {**best["terms"], "unit_price": price}
            c = offers.cost(case, terms, std, model)
            if c is not None:
                out.append({**best, "terms": terms, "price": price, "c": round(c, 2), "mid": best["mid"]})
    return out


def _mirror(case, alt, std):
    """Our term sheet with exactly the terms of the supplier's alternative package."""
    terms = {f: alt["terms"].get(f, std.get(f)) for f in case["negotiable"]}
    if any(v is None and f in ("unit_price",) for f, v in terms.items()):
        return None
    return {
        "mid": "M1",
        "level": "trade",
        "terms": terms,
        "c": alt["cost"],
        "saving": 0.0,
        "price": terms.get("unit_price"),
        "changes": {},
    }


def _fallback_sheet(case, led, std, model, must_beat):
    """No package fits the plan (e.g. the cost model rejects every lower price): never send prose only -
    ask for its own levers at a slightly lower price, if that is cheaper for us."""
    terms = {f: led["terms"].get(f, std.get(f)) for f in case["negotiable"]}
    if any(v is None for v in terms.values()):
        return []
    for cut in (0.02, 0.01, 0.005):
        t = {**terms, "unit_price": round(terms["unit_price"] * (1 - cut), 2)}
        c = offers.cost(case, t, std, model)
        if c is not None and c < must_beat - 0.5:
            return [
                {
                    "mid": "M1",
                    "level": "step",
                    "terms": t,
                    "c": round(c, 2),
                    "saving": round(must_beat - c, 2),
                    "price": t["unit_price"],
                    "changes": {},
                }
            ]
    return []


# Concession: we always move a little (a supplier gives nothing without a move from us - practice runs in
# which we held our position ran into its final offer at its own price: P07, P11, P18), more when it moves,
# most in the end game; we never jump to its offer.
STALL_SHARE = 0.10  # share of the remaining gap we concede when it did not move
MOVE_SHARE = 0.10  # share of the remaining gap we concede when it moved ...
RECIPROCITY = 0.5  # ... plus this share of its concession (in value to it)
MAX_SHARE = 0.4  # never more than this share of the remaining gap before the end game
END_SHARE = 0.3  # share of the remaining gap per round in the end game


def concession_values(s, k, horizon, v_asp, v_stand, drop_mult=1.0):
    """Supplier-value target of our next ask ("step")."""
    prev = s.get("v_ask", v_asp)
    their = max(0.0, (s.get("v_stand_prev") or v_stand) - v_stand)
    remaining = max(0.0, v_stand - prev)
    soft = 1.0 / max(drop_mult, 0.5)  # a learned "concede less" knob shrinks our moves
    if k == 0:
        step = v_asp
    elif k >= horizon - 2:
        step = prev + END_SHARE * remaining
    elif their <= 1e-6:
        step = prev + STALL_SHARE * soft * remaining
    else:
        step = prev + min(MAX_SHARE * remaining, MOVE_SHARE * soft * remaining + RECIPROCITY * soft * their)
    step = min(max(step, prev), v_stand)
    return {"step": step}


def after_menu(ctx):
    if ctx["route"]["type"] == "close":
        return "close"
    return {"merged": "negotiator", "two": "strategist"}.get(ctx["mode"], "det")


# --- choose ---------------------------------------------------------------------------------------


def _det_choices(ctx):
    out = {}
    knobs = ctx["mem"].get("knobs") or {}
    for sid in ctx["route"]["suppliers"]:
        led = ctx["ledgers"][sid]
        out[sid] = policy.det_choose(
            sid,
            led,
            ctx["menus"].get(sid) or [],
            ctx["claims"].get(sid) or [],
            ctx["state"]["sup"][sid].get("tags") or [],
            ctx["route"]["final_push"].get(sid, False),
            led["rounds"] == 0,
            knobs,
        )
        out[sid]["source"] = "det"
        if (ctx.get("mirrors") or {}).get(sid):
            out[sid].update(tactic="conclude", ask_breakdown=False, claim_ids=[], questions=[])
    return out


def det(ctx):
    return {"choices": _det_choices(ctx)}


def _case_summary(ctx):
    case, b = ctx["case"], ctx["case"]["buyer"]
    return {
        "case_id": case.get("case_id"),
        "type": case.get("type"),
        "title": case.get("title"),
        "briefing": (case.get("briefing") or "")[:800],
        "goal": b.get("category_goal"),
        "need_per_year": b.get("need_per_year"),
        "horizon_years": b.get("horizon_years"),
        "current_unit_price": b.get("current_unit_price"),
        "our_alternative_cost_eur": ctx.get("c_alt"),
        "negotiable": case.get("negotiable"),
        "must_haves": b.get("must_haves"),
        "round_limit": case.get("round_limit", 10),
    }


def _payload(ctx, with_plan=True):
    state, dossier = ctx["state"], ctx["cc"]["dossier"]
    suppliers = {}
    for sid in ctx["route"]["suppliers"]:
        s, led = state["sup"][sid], ctx["ledgers"][sid]
        suppliers[sid] = {
            "dossier": dossier_mod.digest(dossier, sid),
            "advice": advice_for(s.get("tags") or []),
            "ledger": ledger_mod.digest(led),
            "preferences": s.get("preferences") or {},
            "final_offer_push": ctx["route"]["final_push"].get(sid, False),
            "menu": [
                {
                    "mid": m["mid"],
                    "level": m["level"],
                    "terms": offers.describe(ctx["case"], m["terms"]),
                    "c": m["c"],
                    "saving": m["saving"],
                }
                for m in ctx["menus"].get(sid) or []
            ],
            "claims": [
                {"cid": c["cid"], "kind": c["kind"], "sentence": c["sentence"], "reveals_private_data": c["reveals"]}
                for c in ctx["claims"].get(sid) or []
            ][:8],
            "our_previous_read": s.get("read"),
            **({"our_plan": s.get("plan")} if with_plan else {}),
        }
    return {
        "case": _case_summary(ctx),
        "trigger_letter": (dossier.get("trigger") or {}).get("text"),
        "lessons": [
            {
                "key": x["key"],
                "scope": f"{x['scope']['level']}:{x['scope']['value']}",
                "do_or_avoid": x["polarity"],
                "lesson": x["text"],
                "confidence": x["confidence"],
            }
            for x in ctx["mem"].get("lessons") or []
        ],
        "suppliers": suppliers,
    }


def _merge_choices(ctx, raw):
    """Model choices per supplier, each validated; the deterministic choice fills every gap. A reply
    that gives no usable supplier entry counts as a model failure (two turn the model off)."""
    det_c = _det_choices(ctx)
    try:
        entries = prompts.supplier_entries(raw, ctx["route"]["suppliers"])
    except Exception:
        entries = {}
    out, used = {}, 0
    for sid in ctx["route"]["suppliers"]:
        try:
            raw_choice = entries.get(sid)
            s = ctx["state"]["sup"][sid]
            pref = preferences.update(
                ctx["case"],
                ctx["ledgers"][sid],
                s.get("preferences") or {},
                (raw_choice or {}).get("signals") if isinstance(raw_choice, dict) else [],
            )
            s["preferences"] = pref
            out[sid] = prompts.clean_choice(
                entries.get(sid), ctx["menus"].get(sid) or [], ctx["claims"].get(sid) or [], det_c[sid]
            )
            choice = out[sid]
            if (ctx.get("mirrors") or {}).get(sid):
                out[sid] = dict(det_c[sid], source="det")
                continue
            candidates = ctx["menus"].get(sid) or []
            fields = pref.get("fields") or {}
            if (
                fields
                and candidates
                and not any(all(m["terms"].get(f) in p["values"] for f, p in fields.items()) for m in candidates)
            ):
                # A countercondition the model just evidenced: add it, repriced to the same cost for us.
                led = ctx["ledgers"][sid]
                extra = [
                    {**m, "mid": f"P{i}"}
                    for i, m in enumerate(
                        within_band(
                            (ctx.get("fulls") or {}).get(sid) or [],
                            ctx["case"],
                            led["std"],
                            led["model"],
                            pref,
                            led.get("price"),
                        ),
                        1,
                    )
                    if all(m["terms"].get(f) in p["values"] for f, p in fields.items())
                ]
                candidates.extend(extra)
                ctx["menus"][sid] = candidates
            selected = [m for m in candidates if m["mid"] in choice["sheet_ids"]]
            if selected and pref.get("fields"):
                same_level = [m for m in candidates if m["level"] == selected[0]["level"]]
                ranked = preferences.rank(same_level, pref)
                # A current, evidenced countercondition outranks a stale model choice.
                if ranked:
                    best = ranked[0]
                    if any(m["terms"].get(f) not in p["values"] for m in selected for f, p in pref["fields"].items()):
                        choice["sheet_ids"] = [best["mid"]]
                        choice["body"] = ""  # render fresh prose when the evidenced terms changed
            _proposal(ctx, sid, raw_choice, choice)
            used += out[sid].get("source") == "llm"
        except Exception:
            out[sid] = dict(det_c[sid], source="det")
    if not used:
        ctx["state"]["llm"]["fails"] = ctx["state"]["llm"].get("fails", 0) + 1
    return out


def _proposal(ctx, sid, raw, choice):
    """The model can request allowed non-price terms; code solves the price and checks cost."""
    proposal = raw.get("proposal") if isinstance(raw, dict) else None
    if not isinstance(proposal, dict) or not proposal or sid not in ctx.get("vals", {}):
        return
    case, led = ctx["case"], ctx["ledgers"][sid]
    if any(
        f == "unit_price" or f not in case["negotiable"] or v not in case.get("term_options", {}).get(f, [])
        for f, v in proposal.items()
    ):
        return
    s = ctx["state"]["sup"][sid]
    if any(
        f in proposal and proposal[f] not in p["values"] for f, p in s.get("preferences", {}).get("fields", {}).items()
    ):
        return
    model = led["model"]
    restricted = {**case, "term_options": {**case.get("term_options", {}), **{f: [v] for f, v in proposal.items()}}}
    # Include proposed terms in the base so lever_domains does not re-add the old value.
    std = {**led["std"], **proposal}
    v_asp, v_stand = ctx["vals"][sid]
    level = raw.get("level") if raw.get("level") in ctx["shares"][sid] else "step"
    menu = offers.build_menu(
        restricted, led, model, std, v_asp, v_stand, {level: ctx["shares"][sid].get(level, 0)}, led["c"] or math.inf
    )
    if menu:
        selected = preferences.rank(menu, s.get("preferences") or {})[0]
        selected["mid"] = "proposal"
        ctx["menus"][sid].append(selected)
        choice["sheet_ids"] = [selected["mid"]]
        choice["body"] = ""


def negotiator(ctx):
    raw = ctx["gw"].json(prompts.negotiator(_payload(ctx), write=True))
    return {"choices": _merge_choices(ctx, raw)}


def strategist(ctx):
    raw = ctx["gw"].json(prompts.negotiator(_payload(ctx), write=False))
    return {"choices": _merge_choices(ctx, raw)}


def write(ctx):
    choices = ctx["choices"]
    if not ctx["budget"].can_call() or not any(c.get("source") == "llm" for c in choices.values()):
        return {}
    payload = {
        "case": _case_summary(ctx),
        "suppliers": {
            sid: {
                "dossier": dossier_mod.digest(ctx["cc"]["dossier"], sid),
                "latest_email": ctx["ledgers"][sid].get("body"),
                "decision": {k: c.get(k) for k in ("read", "tactic", "tone", "ask_breakdown", "questions", "plan")},
                "packages": [
                    offers.describe(ctx["case"], m["terms"])
                    for m in ctx["menus"].get(sid) or []
                    if m["mid"] in c.get("sheet_ids", [])
                ],
                "claims": [x["cid"] for x in ctx["claims"].get(sid) or [] if x["cid"] in c.get("claim_ids", [])],
            }
            for sid, c in choices.items()
        },
    }
    raw = ctx["gw"].json(prompts.writer(payload))
    emails = (raw or {}).get("emails") if isinstance((raw or {}).get("emails"), dict) else {}
    for sid, c in choices.items():
        e = emails.get(sid) if isinstance(emails.get(sid), dict) else {}
        c["body"] = str(e.get("body") or c.get("body") or "")[:3000]
    return {"choices": choices}


# --- critic ---------------------------------------------------------------------------------------


def critic(ctx):
    case, threads, state = ctx["case"], ctx["threads"], ctx["state"]
    actions, batch = [], set()  # IDs cited earlier in this batch count as used for the next supplier
    for sid in ctx["route"]["suppliers"]:
        choice = ctx["choices"][sid]
        menu_by_id = {m["mid"]: m for m in ctx["menus"].get(sid) or []}
        sheets = [menu_by_id[m]["terms"] for m in choice.get("sheet_ids") or [] if m in menu_by_id]
        chosen = [
            c
            for c in ctx["claims"].get(sid) or []
            if c["cid"] in (choice.get("claim_ids") or []) and not (set(c["ids"]) & batch)
        ]
        wanted = len(choice.get("claim_ids") or [])
        for c in ctx["claims"].get(sid) or []:  # replace claims another supplier of this batch just got
            if len(chosen) >= wanted:
                break
            if c not in chosen and not c.get("reveals") and not (set(c["ids"]) & batch):
                chosen.append(c)
        batch.update(i for c in chosen for i in c["ids"] if not i.startswith(claims_mod.PER_SUPPLIER))
        questions = []
        pref = state["sup"][sid].get("preferences") or {}
        for q in choice.get("questions") or []:
            q = preferences.filter_questions(q, pref)
            text, issues = writer.lint(q)
            if text and not issues:
                questions.append(text)
        if (
            choice.get("ask_breakdown")
            and preferences.can_ask_breakdown(pref)
            and not ctx["ledgers"][sid].get("breakdown")
            and not any("breakdown" in q.lower() for q in questions)
        ):
            questions.append("Could you send us a cost breakdown for this part?")
        led = ctx["ledgers"][sid]
        hold = (ctx["route"].get("hold") or {}).get(sid, False)
        if hold:  # no sheets, no arguments: a polite holding reply that does not push its final offer
            sheets, chosen, questions = [], [], []
            choice = {**choice, "body": "", "tactic": "review", "sheet_ids": []}
        body_src, issues = writer.lint(preferences.filter_questions(choice.get("body") or "", pref))
        if len(body_src) < 40:
            body_src = writer.finish_template(
                writer.template(
                    case, choice.get("tone"), choice.get("tactic"), bool(sheets), False, led["rounds"] == 0
                ),
                chosen,
            )
        body, refs, emitted = writer.compose(case, body_src, chosen, sheets, questions)
        by_cid = {c["cid"]: c for c in chosen}
        emitted = [by_cid[c] for c in emitted if c in by_cid]
        subject = writer.subject(case, _thread_subject(threads[sid]))
        message = {"subject": subject, "body": body, "term_sheets": [{"terms": t} for t in sheets], "refs": refs}
        action = {"supplier_id": sid, "message": message}
        try:
            validate(case, threads, [action])
        except Exception:
            message = {"subject": subject, "body": writer.SIGNATURE_FALLBACK, "term_sheets": [], "refs": []}
            action = {"supplier_id": sid, "message": message}
            sheets, emitted, refs = [], [], []
        actions.append(action)
        s = state["sup"][sid]
        level = (menu_by_id.get((choice.get("sheet_ids") or [None])[0]) or {}).get("level")
        if sheets and level in (ctx["shares"].get(sid) or {}) and sid in (ctx.get("vals") or {}):
            v_asp, v_stand = ctx["vals"][sid]
            s["f"] = ctx["shares"][sid][level]
            s["v_ask"] = v_asp + s["f"] * (v_stand - v_asp)
            s["c_ask"] = _dearest(case, sheets, led["std"], led.get("model"))
        s["sent_at"] = time.time()
        s["last_status"] = led["status"]
        if choice.get("read"):
            s["read"] = choice["read"]
        if choice.get("plan"):
            s["plan"] = choice["plan"]
        state["log"].append(
            {
                "r": led["rounds"],
                "sup": sid,
                "mode": ctx.get("mode"),
                "src": choice.get("source"),
                "tactic": choice.get("tactic"),
                "level": level,
                "share": round(s.get("f", 0.0), 3),
                "sheets": [
                    {"price": m["price"], "c": m["c"]}
                    for m in menu_by_id.values()
                    if m["mid"] in (choice.get("sheet_ids") or [])
                ][:3]
                if sheets
                else [],
                "refs": refs,
                "claims": [{"kind": c["kind"], "ids": c["ids"]} for c in emitted],
                "claim_kinds": [c["kind"] for c in emitted],
                "tone": choice.get("tone"),
                "pred": choice.get("prediction"),
                "lessons": state.get("mem", {}).get("lessons", [])[:10],
            }
        )
    return {"actions": actions}


def _dearest(case, sheets, std, model=None):
    """Our cost of the dearest sheet we sent, priced like the ledger prices its offers: any of them is a
    deal we asked for."""
    costs = []
    for t in sheets:
        try:
            c = offers.cost(case, t, std, model or {})
            if c is None:
                return None
            costs.append(c)
        except Exception:
            return None
    finite = [c for c in costs if math.isfinite(c)]
    return max(finite) if finite and len(finite) == len(costs) else None


def _thread_subject(events):
    for m in events:
        if m.get("from") != "buyer" and m.get("subject"):
            return m["subject"]
    return None


# --- runners --------------------------------------------------------------------------------------

NODES = {
    "observe": observe,
    "route": route,
    "close": close,
    "menu": menu,
    "negotiator": negotiator,
    "strategist": strategist,
    "writer": write,
    "det": det,
    "critic": critic,
}


def after_route(ctx):
    return "close" if ctx["route"]["type"] == "close" else "menu"


def build_langgraph():
    from langgraph.graph import END, StateGraph

    g = StateGraph(Ctx)
    for name, fn in NODES.items():
        g.add_node(name, fn)
    g.set_entry_point("observe")
    g.add_edge("observe", "route")
    g.add_conditional_edges("route", after_route, {"close": "close", "menu": "menu"})
    g.add_edge("close", END)
    g.add_conditional_edges(
        "menu", after_menu, {"close": "close", "negotiator": "negotiator", "strategist": "strategist", "det": "det"}
    )
    g.add_edge("strategist", "writer")
    g.add_edge("writer", "critic")
    g.add_edge("negotiator", "critic")
    g.add_edge("det", "critic")
    g.add_edge("critic", END)
    return g.compile()


def run_sequential(ctx):
    """The same graph without LangGraph (used if it cannot be imported)."""

    def step(name):
        ctx.update(NODES[name](ctx) or {})

    step("observe")
    step("route")
    if after_route(ctx) == "menu":
        step("menu")
        nxt = after_menu(ctx)
        if nxt != "close":
            if nxt == "strategist":
                step("strategist")
                step("writer")
            else:
                step(nxt)
            step("critic")
            return ctx
    step("close")
    return ctx


_GRAPH = None


def run(ctx):
    global _GRAPH
    try:
        if _GRAPH is None:
            _GRAPH = build_langgraph()
        runner = _GRAPH
    except Exception:
        runner = None
    if runner is None:
        return run_sequential(ctx), "sequential"
    out = runner.invoke(ctx, {"recursion_limit": 20})
    return out, "langgraph"

